import assert from "node:assert";
import * as fs from "node:fs";
import * as path from "node:path";
import * as vite from "vite";
import { MAIN_ENTRY_NAME } from "../cloudflare-environment";
import { assertIsNotPreview } from "../context";
import { writeDeployConfig } from "../deploy-config";
import { getLocalDevVarsForPreview } from "../dev-vars";
import { createPlugin } from "../utils";
import type { ResolvedWorkerConfig } from "../plugin-config";
import type { Unstable_RawConfig } from "wrangler";

/**
 * Plugin to generate additional output files as part of the build, including the output `wrangler.json` file.
 */
export const outputConfigPlugin = createPlugin("output-config", (ctx) => {
	return {
		generateBundle(_, bundle) {
			assertIsNotPreview(ctx);

			// Child environments should not emit wrangler.json or .dev.vars files
			if (ctx.isChildEnvironment(this.environment.name)) {
				return;
			}

			let outputConfig: Unstable_RawConfig | undefined;

			const inputWorkerConfig = ctx.getWorkerConfig(this.environment.name);

			if (inputWorkerConfig) {
				const entryChunk = Object.values(bundle).find(
					(chunk) =>
						chunk.type === "chunk" &&
						chunk.isEntry &&
						chunk.name === MAIN_ENTRY_NAME
				);

				assert(
					entryChunk,
					`Expected entry chunk with name "${MAIN_ENTRY_NAME}"`
				);

				const isPrerenderWorker =
					this.environment.name ===
					ctx.resolvedPluginConfig.prerenderWorkerEnvironmentName;
				const isEntryWorker =
					ctx.resolvedPluginConfig.type === "workers" &&
					this.environment.name ===
						ctx.resolvedPluginConfig.entryWorkerEnvironmentName;

				outputConfig = getOutputConfig({
					inputWorkerConfig,
					workerOutputDirectory: this.environment.config.build.outDir,
					resolvedViteConfig: ctx.resolvedViteConfig,
					entryFileName: entryChunk.fileName,
					includeAssets: isEntryWorker || isPrerenderWorker,
				});

				// Infer `upload_source_maps` from Vite's `build.sourcemap` if not explicitly set
				if (
					inputWorkerConfig.upload_source_maps === undefined &&
					this.environment.config.build.sourcemap
				) {
					outputConfig.upload_source_maps = true;
				}

				if (inputWorkerConfig.configPath) {
					const localDevVars = getLocalDevVarsForPreview(
						inputWorkerConfig,
						ctx.resolvedPluginConfig.cloudflareEnv
					);
					// Save a .dev.vars file to the worker's build output directory if there are local dev vars, so that it will be then detected by `vite preview`.
					if (localDevVars) {
						this.emitFile({
							type: "asset",
							fileName: ".dev.vars",
							source: localDevVars,
						});
					}
				}
			} else if (this.environment.name === "client") {
				const filesToAssetsIgnore = ["wrangler.json", ".dev.vars"] as const;
				const existingAssetsIgnoreContent =
					ctx.resolvedViteConfig.publicDir.length > 0
						? readAssetsIgnoreFile(
								path.join(ctx.resolvedViteConfig.publicDir, ".assetsignore")
							)
						: "";

				this.emitFile({
					type: "asset",
					fileName: ".assetsignore",
					source: `${existingAssetsIgnoreContent}${filesToAssetsIgnore.join("\n")}\n`,
				});

				// For assets only projects the `wrangler.json` file is emitted in the client output directory
				if (ctx.resolvedPluginConfig.type === "assets-only") {
					const inputAssetsOnlyConfig = ctx.resolvedPluginConfig.config;

					outputConfig = {
						...inputAssetsOnlyConfig,
						assets: {
							...inputAssetsOnlyConfig.assets,
							directory: ".",
						},
					};
				}
			}

			if (!outputConfig) {
				return;
			}

			// Set to `undefined` if it's an empty object so that the user doesn't see a warning about using `unsafe` fields when deploying their Worker.
			if (
				outputConfig.unsafe &&
				Object.keys(outputConfig.unsafe).length === 0
			) {
				outputConfig.unsafe = undefined;
			}

			this.emitFile({
				type: "asset",
				fileName: "wrangler.json",
				source: JSON.stringify(outputConfig),
			});
		},
		writeBundle() {
			assertIsNotPreview(ctx);

			// These conditions ensure the deploy config is emitted once per application build as `writeBundle` is called for each environment.
			if (
				this.environment.name ===
				(ctx.resolvedPluginConfig.type === "workers"
					? ctx.resolvedPluginConfig.entryWorkerEnvironmentName
					: "client")
			) {
				writeDeployConfig(
					ctx.resolvedPluginConfig,
					ctx.resolvedViteConfig,
					ctx.resolvedPluginConfig.type === "assets-only"
				);
			}
		},
	};
});

export function getOutputConfig({
	inputWorkerConfig,
	workerOutputDirectory,
	resolvedViteConfig,
	entryFileName,
	includeAssets,
}: {
	inputWorkerConfig: ResolvedWorkerConfig;
	workerOutputDirectory: string;
	resolvedViteConfig: vite.ResolvedConfig;
	entryFileName: string;
	includeAssets: boolean;
}): Unstable_RawConfig {
	const sourceConfigDirectory = inputWorkerConfig.configPath
		? path.dirname(inputWorkerConfig.configPath)
		: resolvedViteConfig.root;
	const outputDirectory = path.resolve(
		resolvedViteConfig.root,
		workerOutputDirectory
	);

	return {
		...inputWorkerConfig,
		main: entryFileName,
		no_bundle: true,
		rules: [{ type: "ESModule", globs: ["**/*.js", "**/*.mjs"] }],
		assets: includeAssets
			? {
					...inputWorkerConfig.assets,
					directory: getAssetsDirectory(
						workerOutputDirectory,
						resolvedViteConfig
					),
				}
			: undefined,
		d1_databases: inputWorkerConfig.d1_databases.map((database) => {
			const sourceMigrationsDir = database.migrations_dir ?? "migrations";
			const sourceMigrationsPath = path.resolve(
				sourceConfigDirectory,
				sourceMigrationsDir
			);

			const outputMigrationsDir = vite.normalizePath(
				path.relative(outputDirectory, sourceMigrationsPath) || "."
			);

			return {
				...database,
				migrations_dir: outputMigrationsDir,
				migrations_pattern: rewriteMigrationsPattern(
					database.migrations_pattern,
					sourceMigrationsDir,
					outputMigrationsDir
				),
			};
		}),
	};
}

function rewriteMigrationsPattern(
	migrationsPattern: string | undefined,
	fromMigrationsDir: string,
	toMigrationsDir: string
): string | undefined {
	if (migrationsPattern === undefined) {
		return undefined;
	}

	const normalizedDir = path.posix.normalize(
		vite.normalizePath(fromMigrationsDir)
	);
	const normalizedPattern = path.posix.normalize(
		vite.normalizePath(migrationsPattern)
	);
	const suffix =
		normalizedDir === "."
			? normalizedPattern
			: path.posix.relative(normalizedDir, normalizedPattern);

	return vite.normalizePath(
		path.posix.normalize(
			toMigrationsDir === "." ? suffix : `${toMigrationsDir}/${suffix}`
		)
	);
}

function readAssetsIgnoreFile(assetsIgnorePath: string): string {
	const content = fs.existsSync(assetsIgnorePath)
		? fs.readFileSync(assetsIgnorePath, "utf-8")
		: "";
	if (content.length === 0) {
		return "";
	}
	return content.at(-1) === "\n" ? content : `${content}\n`;
}

function getAssetsDirectory(
	workerOutputDirectory: string,
	resolvedViteConfig: vite.ResolvedConfig
): string {
	const clientOutputDirectory =
		resolvedViteConfig.environments.client?.build.outDir;

	assert(
		clientOutputDirectory,
		"Unexpected error: client output directory is undefined"
	);

	return vite.normalizePath(
		path.relative(
			path.resolve(resolvedViteConfig.root, workerOutputDirectory),
			path.resolve(resolvedViteConfig.root, clientOutputDirectory)
		)
	);
}
